$button-padding: 12px 24px;
$button-font-size-icon: 24px;
$buton-line-heigth: 26px;

$button-padding-puffy: 16px 32px;
$button-font-size-puffy: 20px;
$button-font-size-icon-puffy: 24px;
$buton-line-heigth-puffy: 26px;

$button-padding-small: 8px 16px;
$button-font-size-small: 16px;
$buton-font-size-icon-small: 20px;
$buton-line-heigth-small: 24px;

$buton-hug-padding: 24px;

$buton-gap: 8px;



@mixin button-style-states($hover-color,
    $disabled-color,
    $pressed-color,
    $disabled-color-text,
    $background-color,
    $text-color,
    $border:none
    ) {

    background-color: $background-color;
    color: $text-color;
    border: $border;
    &:hover:enabled {
        background-color: $hover-color;
    }

    &:active:enabled {
        background-color: $pressed-color;
    }

    &:disabled {
        background-color: $disabled-color;
        color: $disabled-color-text;
        border-color: $disabled-color-text;
    }

    &:focus-visible{
        outline: var(--outline-color-focus) auto 1px;
    }
}

:host {
    .btn {
        justify-content: center;
        align-items: center;
        border-style: none;
        cursor: pointer;
        padding: $button-padding;
        outline: 0;
        text-transform: none;
        text-decoration: none;
        font-family: var(--cib-sans-font);
        font-size: 18px;
        font-style: normal;
        font-weight: 700;
        border-radius: var(--border-radius-full);
        overflow: hidden;
        width: 100%;
        height: auto;
        white-space: initial;
        display: flex;
        gap: $buton-gap;
        line-height: $buton-line-heigth;

        &:disabled {
            cursor: default;
        }

        &:hover:enabled {
            box-shadow: none;
        }

        &:active:enabled {
            box-shadow: none;
        }

        .icon {
            font-size: $button-font-size-icon;
            color: inherit;
        }
    }

    .button-primary {
        @include button-style-states(var(--button-primary-state-hover),
            var(--button-primary-state-disabled),
            var(--button-primary-state-pressed),
            var(--button-primary-text-icon-disabled),
            var(--button-primary-state-default),
            var(--button-primary-text-icon-default)
            );
    }

    .button-secondary-inverse {
        @include button-style-states(var(--button-secondary-inverse-state-hover),
            '',
            var(--button-secondary-inverse-state-pressed),
            var(--button-secondary-inverse-text-icon-disabled),
            transparent,
            var(--button-secondary-inverse-text-icon-default),
            1px solid var(--button-secondary-inverse-border-default)
            );
    }

    .button-secondary {
        @include button-style-states(var(--button-secondary-state-hover),
            var(--button-secondary-state-disabled),
            var(--button-secondary-state-pressed),
            var(--button-secondary-border-disabled),
            transparent,
            var(--button-secondary-text-icon-default),
            1px solid var(--button-secondary-border-default)
            );
    }

    .button-tertiary {
        background-color: var(--button-tertiary-default);
        @include button-style-states(var(--button-tertiary-hover),
            var(--button-tertiary-disabled),
            var(--button-tertiary-pressed),
            var(--button-primary-text-icon-disabled),
            var(--button-tertiary-default),
            '');
    }

    .button-ghost {
        @include button-style-states(var(--button-ghost-hover),
            '',
            var(--button-ghost-pressed),
            var(--button-primary-text-icon-disabled),
            transparent,
            var(--button-ghost-text-icon-default));

        span {
            text-decoration: underline;
        }
    }

    .button-background {
        @include button-style-states(var(--button-background-color-state-hover),
            var(--button-background-color-state-disabled),
            var(--button-background-color-state-pressed),
            var(--button-background-color-text-icon-disabled),
            var(--button-background-color-state-default),
            var(--button-background-color-text-icon-default));
    }

    .button-small {
        padding: $button-padding-small;
        font-size: $button-font-size-small;
        line-height: $buton-line-heigth-small;

        .icon {
            font-size: $buton-font-size-icon-small;
        }
    }

    .button-puffy {
        padding: $button-padding-puffy;
        font-size: $button-font-size-puffy;
        line-height: $buton-line-heigth-puffy;

        .icon {
            font-size: $button-font-size-icon-puffy;
        }
    }

    .button-hug {
        width: fit-content;
        padding-left: $buton-hug-padding;
        padding-right: $buton-hug-padding;
    }

    .button-icon-left {
        display: flex;
        flex-direction: row-reverse;
    }
}
